 tools.exec_command({cmd:'"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" --help; cat "$STAMPED_ASSESSMENT_VERSION"',max_output_tokens:3000})
]); for (const r of rs) text(r.output);

