const rs=await Promise.all([
 tools.exec_command({cmd:'cat probes.json; cat response.json',max_output_tokens:5000}),
 tools.exec_command({cmd:'cat replay/replay.json 2>/dev/null; cat replay/runner.stdout; cat replay/runner.stderr; cat replay/runner.exit; cat replay/runner-actual.stdout; cat replay/runner-actual.stderr; cat replay/runner-actual.exit; find replay -maxdepth 2 -type f -print',max_output_tokens:2000}),
 tools.exec_command({cmd:'cat "$STAMPED_ASSESSMENT_VERSION"; "$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response encode --help; "$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response template --help',max_output_tokens:1000})
]);for(const r of rs){text(r.output);text(`exit=${r.exit_code}`)}

